import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container – the adapter will position/rotate/scale it.
  const root = new Group();

  // ---- Geometry ---------------------------------------------------------
  // Use the atlas source rect to compute aspect ratio.
  const atlas = (config.atlasRegion ||
    config.intent?.visualSpec?.atlasRegion ||
    { width: 512, height: 320 });
  const aspect = atlas.width / atlas.height; // 1.6

  const geometry = new PlaneGeometry(aspect, 1);
  // UV offset for the atlas region (assuming full texture UV 0‑1).
  // The texture is expected to contain the whole atlas; we shift UVs.
  const uOffset = atlas.x / atlas.width;
  const vOffset = atlas.y / atlas.height;
  const uScale = atlas.width / atlas.width;
  const vScale = atlas.height / atlas.height;
  geometry.attributes.uv.array[0] = uOffset;
  geometry.attributes.uv.array[1] = vOffset + vScale;
  geometry.attributes.uv.array[2] = uOffset + uScale;
  geometry.attributes.uv.array[3] = vOffset + vScale;
  geometry.attributes.uv.array[4] = uOffset;
  geometry.attributes.uv.array[5] = vOffset;
  geometry.attributes.uv.array[6] = uOffset + uScale;
  geometry.attributes.uv.array[7] = vOffset;
  geometry.attributes.uv.needsUpdate = true;

  // ---- Material ---------------------------------------------------------
  const material = new MeshBasicNodeMaterial();
  material.transparent = true;
  material.depthWrite = false;

  // ---- Mesh -------------------------------------------------------------
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // ---- Texture loading (async, but we keep function sync) -----------------
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // ---- Billboard behaviour -----------------------------------------------
  // Expect the runtime to call root.userData.handlers.update({camera})
  root.userData.handlers = {
    update: (payload) => {
      if (payload?.camera) {
        // Keep the plane facing the camera (simple billboard)
        const camPos = payload.camera.position;
        root.lookAt(camPos.x, camPos.y, camPos.z);
      }
    },
  };

  // ---- Cleanup -----------------------------------------------------------
  root.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();
    // Dispose texture if it was loaded
    if (loadedTexture) loadedTexture.dispose();
    // Kill any GSAP timelines that might have been created (none here)
    gsap.globalTimeline.clear();
  };

  // No primitives or text to process for this node
  return root;
}
